   276|function drawRadar(canvas, values) {
   277|  const ratio = Math.min(devicePixelRatio || 1, 2);
   278|  const size = 118;
   279|  canvas.width = size * ratio;
   280|  canvas.height = size * ratio;
   281|  const ctx = canvas.getContext("2d");
   282|  ctx.scale(ratio, ratio);
   283|  const center = size / 2;
   284|  const radius = 43;
   285|  const labels = ["反应", "专注", "记忆", "准确", "心流"];
   286|  const data = [values.reaction, values.focus, values.memory, values.accuracy, values.flow];
   287|  const point = (index, scale = 1) => {
   288|    const angle = -Math.PI / 2 + index * Math.PI * 2 / 5;
   289|    return [center + Math.cos(angle) * radius * scale, center + Math.sin(angle) * radius * scale];
   290|  };
   291|  for (const scale of [.33, .66, 1]) {
   292|    ctx.beginPath();
   293|    for (let i = 0; i < 5; i += 1) {
   294|      const [x, y] = point(i, scale);
   295|      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
   296|    }
   297|    ctx.closePath(); ctx.strokeStyle = "rgba(255,255,255,.11)"; ctx.stroke();
   298|  }
   299|  ctx.beginPath();
   300|  data.forEach((value, index) => {
   301|    const [x, y] = point(index, value / 100);
   302|    if (index === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
   303|  });
   304|  ctx.closePath(); ctx.fillStyle = "rgba(85,223,170,.22)"; ctx.fill(); ctx.strokeStyle = "#55dfaa"; ctx.lineWidth = 1.5; ctx.stroke();
