     3|export const GOAL_WEIGHTS = {
     4|  balanced: { reaction: 0.22, focus: 0.24, memory: 0.22, accuracy: 0.18, flow: 0.14 },
     5|  reaction: { reaction: 0.4, focus: 0.18, memory: 0.15, accuracy: 0.17, flow: 0.1 },
     6|  focus: { reaction: 0.15, focus: 0.4, memory: 0.15, accuracy: 0.15, flow: 0.15 },
     7|  exam: { reaction: 0.12, focus: 0.22, memory: 0.45, accuracy: 0.13, flow: 0.08 }
     8|};
     9|
    10|export class FocusEngine {
    11|  constructor(goal = "balanced") {
    12|    this.goal = GOAL_WEIGHTS[goal] ? goal : "balanced";
    13|  }
    14|
    15|  normalize(metrics, baseline) {
    16|    const reactionRatio = baseline.reactionMs / Math.max(metrics.reactionMs, 1);
    17|    return {
    18|      reaction: clamp(70 + (reactionRatio - 1) * 120),
    19|      focus: clamp((metrics.focusMinutes / Math.max(baseline.focusMinutes, 1)) * 72),
    20|      memory: clamp(metrics.memoryAccuracy),
    21|      accuracy: clamp(metrics.rhythmAccuracy),
    22|      flow: clamp(metrics.flowMinutes / Math.max(baseline.flowMinutes, 1) * 75)
    23|    };
    24|  }
    25|
    26|  analyze(metrics, baseline, goal = this.goal) {
    27|    const normalized = this.normalize(metrics, baseline);
    28|    const weights = GOAL_WEIGHTS[goal] || GOAL_WEIGHTS.balanced;
    29|    const score = Math.round(Object.entries(weights).reduce(
    30|      (total, [key, weight]) => total + normalized[key] * weight,
    31|      0
    32|    ));
    33|    const ranked = Object.entries(normalized).sort((a, b) => a[1] - b[1]);
    34|    const weakest = ranked[0][0];
    35|    const strongest = ranked.at(-1)[0];
    36|    return { score, normalized, weakest, strongest, suggestion: this.suggest(normalized, weakest, strongest) };
    37|  }
