     4|export class BeatFlicksRenderer {
     5|  constructor(canvas, chart, callbacks = {}) {
     6|    this.canvas = canvas;
     7|    this.ctx = canvas.getContext("2d");
     8|    this.chart = chart;
     9|    this.callbacks = callbacks;
    10|    this.pool = Array.from({ length: 32 }, () => ({ active: false }));
    11|    this.nextNote = 0;
    12|    this.score = 0;
    13|    this.combo = 0;
    14|    this.maxCombo = 0;
    15|    this.hits = 0;
    16|    this.total = 0;
    17|    this.running = false;
    18|    this.feedback = null;
    19|    this.resizeObserver = new ResizeObserver(() => this.resize());
    20|    this.resizeObserver.observe(canvas);
    21|    this.resize();
    22|  }
    23|
    24|  resize() {
    25|    const rect = this.canvas.getBoundingClientRect();
    26|    const ratio = Math.min(window.devicePixelRatio || 1, 2);
    27|    this.canvas.width = Math.max(1, Math.floor(rect.width * ratio));
    28|    this.canvas.height = Math.max(1, Math.floor(rect.height * ratio));
    29|    this.ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    30|    this.width = rect.width;
    31|    this.height = rect.height;
    32|  }
    33|
    34|  start() {
    35|    this.reset();
    36|    this.running = true;
    37|    this.startedAt = performance.now() + 600;
    38|    this.frame = requestAnimationFrame((time) => this.loop(time));
    39|  }
    40|
    41|  reset() {
    42|    this.pool.forEach((note) => { note.active = false; });
    43|    this.nextNote = 0;
    44|    this.score = 0;
    45|    this.combo = 0;
    46|    this.maxCombo = 0;
    47|    this.hits = 0;
    48|    this.total = 0;
    49|    this.feedback = null;
    50|    this.callbacks.onStats?.(this.stats());
    51|  }
    52|
    53|  stop() {
    54|    this.running = false;
    55|    cancelAnimationFrame(this.frame);
    56|    this.resizeObserver.disconnect();
    57|  }
    58|
    59|  loop(now) {
    60|    if (!this.running) return;
    61|    let elapsed = now - this.startedAt;
    62|    if (elapsed > this.chart.durationMs) {
    63|      this.callbacks.onRound?.(this.stats());
    64|      this.startedAt = now + 850;
    65|      this.pool.forEach((note) => { note.active = false; });
    66|      this.nextNote = 0;
    67|      elapsed = -850;
    68|    }
    69|    this.spawn(elapsed);
    70|    this.expire(elapsed);
    71|    this.draw(elapsed, now);
    72|    this.frame = requestAnimationFrame((time) => this.loop(time));
    73|  }
    74|
    75|  spawn(elapsed) {
    76|    while (this.nextNote < this.chart.notes.length && this.chart.notes[this.nextNote].timestamp - elapsed < 2400) {
    77|      const source = this.chart.notes[this.nextNote++];
    78|      const item = this.pool.find((note) => !note.active);
    79|      if (!item) break;
    80|      Object.assign(item, source, { active: true, judged: false });
    81|    }
    82|  }
    83|
    84|  expire(elapsed) {
    85|    for (const note of this.pool) {
    86|      if (note.active && !note.judged && elapsed - note.timestamp > 145) {
    87|        note.judged = true;
    88|        note.active = false;
    89|        this.applyJudgement("Miss", note.type, elapsed - note.timestamp);
    90|      }
    91|    }
    92|  }
    93|
    94|  gesture(type) {
    95|    if (!this.running) return;
    96|    const elapsed = performance.now() - this.startedAt;
    97|    const candidates = this.pool
    98|      .filter((note) => note.active && !note.judged && note.type === type)
    99|      .map((note) => ({ note, delta: Math.abs(elapsed - note.timestamp) }))
   100|      .sort((a, b) => a.delta - b.delta);
