   103|      this.applyJudgement("Miss", type, best?.delta ?? 999);
   104|      return;
   105|    }
   106|    best.note.judged = true;
   107|    best.note.active = false;
   108|    this.applyJudgement(best.delta <= 70 ? "Perfect" : "Good", type, best.delta);
   109|  }
   110|
   111|  applyJudgement(result, type, delta) {
   112|    this.total += 1;
   113|    if (result === "Perfect") {
   114|      this.combo += 1;
   115|      this.hits += 1;
   116|      this.score += Math.round(1000 * (1 + Math.floor(this.combo / 10) * 0.1));
