   119|      this.hits += 0.7;
   120|      this.score += Math.round(650 * (1 + Math.floor(this.combo / 10) * 0.1));
   121|    } else {
   122|      this.combo = 0;
   123|    }
   124|    this.maxCombo = Math.max(this.maxCombo, this.combo);
   125|    this.feedback = { result, type, delta, at: performance.now() };
   126|    this.callbacks.onJudgement?.(this.feedback);
   127|    this.callbacks.onStats?.(this.stats());
   128|  }
   129|
   130|  stats() {
   131|    return {
   132|      score: this.score,
   133|      combo: this.combo,
   134|      maxCombo: this.maxCombo,
   135|      accuracy: this.total ? Math.round((this.hits / this.total) * 100) : 100
   136|    };
   137|  }
   138|
   139|  draw(elapsed, now) {
   140|    const ctx = this.ctx;
   141|    const w = this.width;
   142|    const h = this.height;
   143|    ctx.clearRect(0, 0, w, h);
   144|    const gradient = ctx.createLinearGradient(0, 0, 0, h);
   145|    gradient.addColorStop(0, "#07191b");
   146|    gradient.addColorStop(1, "#020707");
   147|    ctx.fillStyle = gradient;
   148|    ctx.fillRect(0, 0, w, h);
   149|
   150|    const laneWidth = w / 3;
   151|    for (let lane = 0; lane < 3; lane += 1) {
   152|      ctx.fillStyle = lane % 2 ? "rgba(255,255,255,.025)" : "rgba(255,255,255,.012)";
   153|      ctx.fillRect(lane * laneWidth, 0, laneWidth, h);
   154|      ctx.strokeStyle = "rgba(255,255,255,.07)";
   155|      ctx.beginPath();
   156|      ctx.moveTo(lane * laneWidth, 0);
   157|      ctx.lineTo(lane * laneWidth, h);
   158|      ctx.stroke();
   159|    }
   160|
   161|    const targetY = h - 46;
   162|    ctx.strokeStyle = "rgba(255,255,255,.42)";
   163|    ctx.lineWidth = 2;
   164|    ctx.beginPath();
   165|    ctx.moveTo(10, targetY);
   166|    ctx.lineTo(w - 10, targetY);
   167|    ctx.stroke();
   168|
   169|    for (const note of this.pool) {
   170|      if (!note.active) continue;
